// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 fund, uint256 amount) public {
        vm.assume(fund <= VALUE_CAP);
        fund = bound(fund, 0, 1 ether);
        amount = bound(amount, 0, 1 ether);
        vm.assume(fund >= amount);

        // fund c through its receive() (owner is the test contract)
        vm.deal(address(this), fund);
        (bool okDep,) = address(c).call{value: fund}("");
        assertTrue(okDep);

        // rule: withdrawing amount <= balance must never revert
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(amount > fund || ok);
    }
}
